def compute(vars):
    exposure = vars["v1"]
    maturity_percentage = vars["v2"]
    maturity_amount = exposure * maturity_percentage / 100

    return {
        "value": maturity_amount,
        "trace": {
            "exposure": exposure,
            "maturity_percentage": maturity_percentage,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
